    29  typedef quint32 uint;
    30  typedef quint16 ushort;
    31  typedef quint8 uchar;
    32
    33  namespace   // Private.
    34  {
    35
    36  // Header format of saved files.
    37  uchar targaMagic[12] = { 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, 0 };
    38
    39  enum TGAType {
    40      TGA_TYPE_INDEXED        = 1,
    41      TGA_TYPE_RGB            = 2,
    42      TGA_TYPE_GREY           = 3,
    43      TGA_TYPE_RLE_INDEXED    = 9,
    44      TGA_TYPE_RLE_RGB        = 10,
    45      TGA_TYPE_RLE_GREY       = 11
    46  };
    47
    48  #define TGA_INTERLEAVE_MASK 0xc0
    49  #define TGA_INTERLEAVE_NONE 0x00
    50  #define TGA_INTERLEAVE_2WAY 0x40
    51  #define TGA_INTERLEAVE_4WAY 0x80
    52
    53  #define TGA_ORIGIN_MASK     0x30
    54  #define TGA_ORIGIN_LEFT     0x00
    55  #define TGA_ORIGIN_RIGHT    0x10
    56  #define TGA_ORIGIN_LOWER    0x00
    57  #define TGA_ORIGIN_UPPER    0x20
    58
    59  /** Tga Header. */
    60  struct TgaHeader {
    61      uchar id_length;
    62      uchar colormap_type;
    63      uchar image_type;
    64      ushort colormap_index;
    65      ushort colormap_length;
    66      uchar colormap_size;
    67      ushort x_origin;
    68      ushort y_origin;
    69      ushort width;
    70      ushort height;
    71      uchar pixel_size;
    72      uchar flags;
    73
    74      enum { SIZE = 18 }; // const static int SIZE = 18;
    75  };
    76
    77  static QDataStream &operator>> (QDataStream &s, TgaHeader &head)
    78  {
    79      s >> head.id_length;
    80      s >> head.colormap_type;
    81      s >> head.image_type;
    82      s >> head.colormap_index;
    83      s >> head.colormap_length;
    84      s >> head.colormap_size;
    85      s >> head.x_origin;
    86      s >> head.y_origin;
    87      s >> head.width;
    88      s >> head.height;
    89      s >> head.pixel_size;
    90      s >> head.flags;
    91      /*qDebug() << "id_length: " << head.id_length << " - colormap_type: " << head.colormap_type << " - image_type: " << head.image_type;
    92      qDebug() << "colormap_index: " << head.colormap_index << " - colormap_length: " << head.colormap_length << " - colormap_size: " << head.colormap_size;
    93      qDebug() << "x_origin: " << head.x_origin << " - y_origin: " << head.y_origin << " - width:" << head.width << " - height:" << head.height << " - pixelsize: " << head.pixel_size << " - flags: " << head.flags;*/
    94      return s;
    95  }
    96
    97  static bool IsSupported(const TgaHeader &head)
    98  {
    99      if (head.image_type != TGA_TYPE_INDEXED &&
   100              head.image_type != TGA_TYPE_RGB &&
   101              head.image_type != TGA_TYPE_GREY &&
   102              head.image_type != TGA_TYPE_RLE_INDEXED &&
   103              head.image_type != TGA_TYPE_RLE_RGB &&
   104              head.image_type != TGA_TYPE_RLE_GREY) {
   105          return false;
   106      }
   107      if (head.image_type == TGA_TYPE_INDEXED ||
   108              head.image_type == TGA_TYPE_RLE_INDEXED) {
   109          if (head.colormap_length > 256 || head.colormap_size != 24 || head.colormap_type != 1) {
   110              return false;
   111          }
   112      }
   113      if (head.image_type == TGA_TYPE_RGB ||
   114              head.image_type == TGA_TYPE_GREY ||
   115              head.image_type == TGA_TYPE_RLE_RGB ||
   116              head.image_type == TGA_TYPE_RLE_GREY) {
   117          if (head.colormap_type != 0) {
   118              return false;
   119          }
   120      }
   121      if (head.width == 0 || head.height == 0) {
   122          return false;
   123      }
   124      if (head.pixel_size != 8 && head.pixel_size != 16 &&
   125              head.pixel_size != 24 && head.pixel_size != 32) {
   126          return false;
   127      }
   128      return true;
   129  }
   130
   131  struct Color555 {
   132      ushort b : 5;
   133      ushort g : 5;
   134      ushort r : 5;
   135  };
   136
   137  struct TgaHeaderInfo {
   138      bool rle;
   139      bool pal;
   140      bool rgb;
   141      bool grey;
   142
   143      TgaHeaderInfo(const TgaHeader &tga) : rle(false), pal(false), rgb(false), grey(false)
   144      {
   145          switch (tga.image_type) {
   146          case TGA_TYPE_RLE_INDEXED:
   147              rle = true;
   148          Q_FALLTHROUGH();
   149          // no break is intended!
   150          case TGA_TYPE_INDEXED:
   151              pal = true;
   152              break;
   153
   154          case TGA_TYPE_RLE_RGB:
   155              rle = true;
   156          Q_FALLTHROUGH();
   157          // no break is intended!
   158          case TGA_TYPE_RGB:
   159              rgb = true;
   160              break;
   161
   162          case TGA_TYPE_RLE_GREY:
   163              rle = true;
   164          Q_FALLTHROUGH();
   165          // no break is intended!
   166          case TGA_TYPE_GREY:
   167              grey = true;
   168              break;
   169
   170          default:
   171              // Error, unknown image type.
   172              break;
   173          }
   174      }
   175  };
   176
   177  static bool LoadTGA(QDataStream &s, const TgaHeader &tga, QImage &img)
   178  {
   179      // Create image.
   180      img = QImage(tga.width, tga.height, QImage::Format_RGB32);
   181
   182      TgaHeaderInfo info(tga);
   183
   184      // Bits 0-3 are the numbers of alpha bits (can be zero!)
   185      const int numAlphaBits = tga.flags & 0xf;
   186      // However alpha exists only in the 32 bit format.
   187      if ((tga.pixel_size == 32) && (tga.flags & 0xf)) {
   188          img = QImage(tga.width, tga.height, QImage::Format_ARGB32);
   189
   190          if (numAlphaBits > 8) {
   191              return false;
   192          }
   193      }
   194
   195      uint pixel_size = (tga.pixel_size / 8);
   196      qint64 size = qint64(tga.width) * qint64(tga.height) * pixel_size;
   197
   198      if (size < 1) {
   199  //          qDebug() << "This TGA file is broken with size " << size;
   200          return false;
   201      }
   202
   203      // Read palette.
   204      char palette[768];
   205      if (info.pal) {
   206          // @todo Support palettes in other formats!
   207          const int size = 3 * tga.colormap_length;
   208          const int dataRead = s.readRawData(palette, size);
   209          if (dataRead < 0) {
   210              return false;
   211          }
   212          if (dataRead < size) {
   213              memset(&palette[dataRead], 0, size - dataRead);
   214          }
   215      }
   216
   217      // Allocate image.
   218      uchar *const image = reinterpret_cast<uchar*>(malloc(size));
   219      if (!image) {
   220          return false;
   221      }
   222
   223      bool valid = true;
   224
   225      if (info.rle) {
   226          // Decode image.
   227          char *dst = (char *)image;
   228          qint64 num = size;
   229
   230          while (num > 0) {
   231              if (s.atEnd()) {
   232                  valid = false;
   233                  break;
   234              }
   235
   236              // Get packet header.
   237              uchar c;
   238              s >> c;
   239
   240              uint count = (c & 0x7f) + 1;
   241              num -= count * pixel_size;
   242              if (num < 0) {
   243                  valid = false;
   244                  break;
   245              }
   246
   247              if (c & 0x80) {
   248                  // RLE pixels.
   249                  assert(pixel_size <= 8);
   250                  char pixel[8];
   251                  s.readRawData(pixel, pixel_size);
   252                  do {
   253                      memcpy(dst, pixel, pixel_size);
   254                      dst += pixel_size;
   255                  } while (--count);
   256              } else {
   257                  // Raw pixels.
   258                  count *= pixel_size;
   259                  s.readRawData(dst, count);
   260                  dst += count;
   261              }
   262          }
   263      } else {
   264          // Read raw image.
   265          const int dataRead = s.readRawData((char *)image, size);
   266          if (dataRead < 0) {
   267              free(image);
   268              return false;
   269          }
   270          if (dataRead < size) {
   271              memset(&image[dataRead], 0, size - dataRead);
   272          }
   273      }
   274
   275      if (!valid) {
   276          free(image);
   277          return false;
   278      }
   279
   280      // Convert image to internal format.
   281      int y_start, y_step, y_end;
   282      if (tga.flags & TGA_ORIGIN_UPPER) {
   283          y_start = 0;
   284          y_step = 1;
   285          y_end = tga.height;
   286      } else {
   287          y_start = tga.height - 1;
   288          y_step = -1;
   289          y_end = -1;
   290      }
   291
   292      uchar *src = image;
   293
   294      for (int y = y_start; y != y_end; y += y_step) {
   295          QRgb *scanline = (QRgb *) img.scanLine(y);
   296
   297          if (info.pal) {
   298              // Paletted.
   299              for (int x = 0; x < tga.width; x++) {
   300                  uchar idx = *src++;
   301                  scanline[x] = qRgb(palette[3 * idx + 2], palette[3 * idx + 1], palette[3 * idx + 0]);
   302              }
   303          } else if (info.grey) {
   304              // Greyscale.
   305              for (int x = 0; x < tga.width; x++) {
   306                  scanline[x] = qRgb(*src, *src, *src);
   307                  src++;
   308              }
   309          } else {
   310              // True Color.
   311              if (tga.pixel_size == 16) {
   312                  for (int x = 0; x < tga.width; x++) {
   313                      Color555 c = *reinterpret_cast<Color555 *>(src);
   314                      scanline[x] = qRgb((c.r << 3) | (c.r >> 2), (c.g << 3) | (c.g >> 2), (c.b << 3) | (c.b >> 2));
   315                      src += 2;
   316                  }
   317              } else if (tga.pixel_size == 24) {
   318                  for (int x = 0; x < tga.width; x++) {
   319                      scanline[x] = qRgb(src[2], src[1], src[0]);
   320                      src += 3;
   321                  }
   322              } else if (tga.pixel_size == 32) {
   323                  for (int x = 0; x < tga.width; x++) {
   324                      // ### TODO: verify with images having really some alpha data
   325                      const uchar alpha = (src[3] << (8 - numAlphaBits));
   326                      scanline[x] = qRgba(src[2], src[1], src[0], alpha);
   327                      src += 4;
   328                  }
   329              }
   330          }
   331      }
   332
   333      // Free image.
   334      free(image);
   335
   336      return true;
   337  }
   338
   339  } // namespace
   340
   341  TGAHandler::TGAHandler()
   342  {
   343  }
   344
   345  bool TGAHandler::canRead() const
   346  {
   347      if (canRead(device())) {
   348          setFormat("tga");
   349          return true;
   350      }
   351      return false;
   352  }
   353
   354  bool TGAHandler::read(QImage *outImage)
   355  {
   356      //qDebug() << "Loading TGA file!";
   357
   358      QDataStream s(device());
   359      s.setByteOrder(QDataStream::LittleEndian);
   360
   361      // Read image header.
   362      TgaHeader tga;
   363      s >> tga;
   364      s.device()->seek(TgaHeader::SIZE + tga.id_length);
   365
   366      // Check image file format.
   367      if (s.atEnd()) {
   368  //         qDebug() << "This TGA file is not valid.";
   369          return false;
   370      }
   371
   372      // Check supported file types.
   373      if (!IsSupported(tga)) {
   374  //         qDebug() << "This TGA file is not supported.";
   375          return false;
   376      }
   377
   378      QImage img;
   379      bool result = LoadTGA(s, tga, img);
   380
   381      if (result == false) {
   382  //         qDebug() << "Error loading TGA file.";
   383          return false;
   384      }
   385
   386      *outImage = img;
   387      return true;
   388  }
   389
   390  bool TGAHandler::write(const QImage &image)
   391  {
   392      QDataStream s(device());
   393      s.setByteOrder(QDataStream::LittleEndian);
   394
   395      const QImage &img = image;
   396      const bool hasAlpha = (img.format() == QImage::Format_ARGB32);
   397      for (int i = 0; i < 12; i++) {
   398          s << targaMagic[i];
   399      }
   400
   401      // write header
   402      s << quint16(img.width());   // width
   403      s << quint16(img.height());   // height
   404      s << quint8(hasAlpha ? 32 : 24);   // depth (24 bit RGB + 8 bit alpha)
   405      s << quint8(hasAlpha ? 0x24 : 0x20);   // top left image (0x20) + 8 bit alpha (0x4)
   406
   407      for (int y = 0; y < img.height(); y++)
   408          for (int x = 0; x < img.width(); x++) {
   409              const QRgb color = img.pixel(x, y);
   410              s << quint8(qBlue(color));
   411              s << quint8(qGreen(color));
   412              s << quint8(qRed(color));
   413              if (hasAlpha) {
   414                  s << quint8(qAlpha(color));
   415              }
   416          }
   417
   418      return true;
   419  }
